local _, WFJ = ...
WFJ.Data.add("book", {
  ["5b03f28a29440c7c"] = { "Re Llane I della Casata dei Wrynn\n\nSovrano di ⟦Stormwind=Roccavento⟧\n\nDifensore di Azeroth", "." },
  ["5b1141849cd80697"] = { "Pelver Deepstomp\n\nIl ⟦Dark Keeper Pelver=Guardiano Oscuro Pelver⟧ è il nostro discepolo più onorato. Ha portato la chiave più a lungo di chiunque altro, e gli è costata cara. Quando viene chiamato al suo fardello, è sorvegliato nel Domicile.\n\nIl suo sacrificio ci è caro, e resterà nei nostri cuori per molti anni... dopo che l'oscurità lo avrà preso.", "." },
  ["5b3337d28031b42f"] = { "Aran era il mago di corte e il consigliere del re di Azeroth. Aegwynn sedusse il mago e concepì un figlio da lui. L'innata affinità di Nielas per la magia sarebbe scorsa profonda nel bambino non ancora nato e avrebbe segnato i tragici passi che il bambino avrebbe compiuto in seguito. Nel bambino fu impiantato anche il potere di Tirisfal, che però non si sarebbe risvegliato finché lui non avesse raggiunto la maturità fisica.", "." },
  ["5b4a0803cd4d13f2"] = { "La prima mossa di Kil'jaeden fu ridurre in schiavitù i vampirici signori del terrore sotto il suo terribile potere. I signori del terrore divennero i suoi agenti personali in tutto l'universo, e si compiacevano di scovare razze primitive che il loro padrone potesse corrompere e accogliere tra le sue file. Il primo tra i signori del terrore era Tichondrius l'Ottenebratore. Tichondrius servì Kil'jaeden come il soldato perfetto e accettò di portare la volontà ardente di Sargeras in tutti gli angoli oscuri dell'universo.", "." },
  ["5b7580665298e550"] = { "aspetti del loro culto del serpente nei volumi precedenti di questo studio, presento qui un esame del rapporto, interessante e unico, dei troll con il mare.\n\nIL GRANDE MARE\n\nL'Impero Gurubashi era circondato dal mare su tre lati, quindi non sorprende che l'acqua avesse un ruolo di primo piano nella sua società. Se i troll riuscivano a percorrere e a dominare le vaste regioni del loro impero nella giungla, il mare sfuggiva loro. Era vasto e incommensurabile, senza", "." },
  ["5b9f9a7766d87bf5"] = { "I Kaldorei, o elfi della notte come sarebbero stati chiamati in seguito, adoravano la dea della luna, Elune, e credevano che durante le ore del giorno dormisse nelle profondità scintillanti del Pozzo. I primi sacerdoti e veggenti degli elfi della notte studiarono il Pozzo con una curiosità insaziabile, spinti a sondarne i segreti e il potere indicibili. Man mano che la loro società cresceva, gli elfi della notte esplorarono\nl'intera Kalimdor e incontrarono i suoi innumerevoli abitanti.", "." },
  ["5bb26395b697e6be"] = { "Le ⟦Venture Co. Letters=Lettere della S.P.R. & Co.⟧ sono fuori dalla miniera... credo su alcune casse al livello più basso.\n\nBuona fortuna, e ricorda...\n\nCarica blu: segheria\nCarica rossa: miniera\n\nAh, e distruggi questa lettera dopo aver portato a termine la tua missione. Mmm, forse dovrei trovare un modo per far sì che queste cose si distruggano da sole dopo essere state lette. Non è una cattiva idea...", "." },
  ["5bfcad782840fd82"] = { "La devastante Seconda Guerra contro l'orda degli orchi lasciò l'⟦Alliance=Alleanza⟧ di Lordaeron sconvolta e allo sbando. Gli orchi assetati di sangue, guidati dal possente capoguerra Orgrim Doomhammer, non solo si aprirono la strada attraverso le terre dei nani di Khaz Modan, ma rasero al suolo anche molte delle province centrali di Lordaeron. Gli implacabili orchi riuscirono perfino a devastare il remoto regno degli\nelfi di Quel'Thalas, prima che la loro furia venisse finalmente fermata.", "." },
})
